  } else {
    O1.Above(y, l, h);
    O2.Above(y, h);
    A.Assemble(y, l, h, y, h);
  }
} else if x <= h {
  O1.Within(x, l, h);
  O2.Within(x, l, h);
  A.Assemble(x, l, h, x, x);
  if y <= h {
    O1.Within(y, l, h);
    O2.Within(y, l, h);
    A.Assemble(y, l, h, y, y);
  } else {
    O1.Above(y, l, h);
    O2.Above(y, h);
    A.Assemble(y, l, h, y, h);
  }
} else {
  O1.Above(x, l, h);
  O2.Above(x, h);
  A.Assemble(x, l, h, x, h);
  O1.Above(y, l, h);
  O2.Above(y, h);
  A.Assemble(y, l, h, y, h);
